export async function charge(confirmationTokenId: string): Promise<void> {
  await fetch(`/charge/${confirmationTokenId}`, { method: "POST" });
}

export async function tokenForSavedCard(paymentMethodId: string): Promise<string> {
  const reply = await fetch(`/tokens/${paymentMethodId}`, { method: "POST" });
  return ((await reply.json()) as { id: string }).id;
}

