import { pay } from "./pay";
import { tokenForSavedCard } from "./stripe";

export async function confirm(card: { savedPaymentMethodId?: string; confirmationTokenId?: string }): Promise<void> {
  const confirmationTokenId =
    card.savedPaymentMethodId === undefined
      ? card.confirmationTokenId
      : await tokenForSavedCard(card.savedPaymentMethodId);
  await pay({ confirmationTokenId });
}
